import { View, Text, StyleSheet } from "react-native";
import { registerRootComponent } from "expo";

function App() {
  return (
    <View style={styles.card}>
      <View style={styles.photo}><Text style={styles.photoText}>Зураг</Text></View>
      <Text nativeID="badge" style={styles.badge}>-20%</Text>
      {/* энд бичнэ үү: badge-г булан дээр наа */}
    </View>
  );
}

const styles = StyleSheet.create({
  card: { margin: 24, width: 200, height: 160, borderRadius: 16, overflow: "hidden" },
  photo: { flex: 1, backgroundColor: "#cbd5e1", alignItems: "center", justifyContent: "center" },
  photoText: { color: "#475569" },
  badge: { backgroundColor: "#dc2626", color: "#fff", fontWeight: "bold", paddingHorizontal: 10, paddingVertical: 4, borderRadius: 999 },
});

registerRootComponent(App);

